PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE position(
  -- The source that declares the struct: a source of a kernel or a storage
  -- crate, or the core term arena, whose ids a session's report holds;
  -- outside the tests.
  file   TEXT NOT NULL CONSTRAINT "file is a source of a kernel or a storage crate, or the core term arena" CHECK((file GLOB 'crates/kernel-*/src/*.rs' OR file GLOB 'crates/storage-*/src/*.rs' OR file = 'crates/core-term/src/arena.rs') AND file NOT GLOB '*[^A-Za-z0-9_/.-]*'),
  -- The struct's name, as `.config/positions/hits.jq` reads it.
  name   TEXT NOT NULL CONSTRAINT "name is an identifier" CHECK(name GLOB '[A-Z]*' AND name NOT GLOB '*[^A-Za-z0-9_]*'),
  -- The key, the name or the byte form that writes the struct, as the path
  -- `<crate>::<module>` of its writer, or of the item when one module writes
  -- the struct in two classes; empty for a struct that none writes.
  reader TEXT NOT NULL CONSTRAINT "reader is empty or a path crate::item" CHECK(reader = '' OR (reader GLOB '[a-z]*-[a-z]*::[a-z]*' AND reader NOT GLOB '*[^A-Za-z0-9_:-]*')),
  -- What the struct is to its reader, the first that holds:
  --   kept   a place inside a piece that its content names: an offset, a
  --          member's place, a count of earlier twins of one content, a
  --          child's place inside one node;
  --   owed   a place relative to an order of admission or of mints;
  --   local  a place that no key, name or byte form writes;
  --   none   no place: a count, a length, a budget, a version, a mask, a
  --          seed, a tag, a hash, a digest, or a carrier of a writer's words.
  class  TEXT NOT NULL CONSTRAINT "class is kept, owed, local or none" CHECK(class IN ('kept', 'owed', 'local', 'none')),
  -- The issue whose unit removes an owed row; NULL for every other class.
  unit   TEXT CONSTRAINT "unit is an issue number" CHECK(unit GLOB '#[1-9]*' AND unit NOT GLOB '#*[^0-9]*'),
  -- Why the row holds its class, in one sentence.
  why    TEXT NOT NULL CONSTRAINT "why is one sentence on one line: a capital first, a full stop last" CHECK(why GLOB '[A-Z]*.' AND instr(why, char(10)) = 0),
  CONSTRAINT "a kept or an owed row names its reader, and a local or a none row names none" CHECK((class IN ('kept', 'owed')) = (reader <> '')),
  CONSTRAINT "an owed row names its unit, and no other row names one" CHECK((class = 'owed') = (unit IS NOT NULL)),
  PRIMARY KEY(file, name, reader)
) WITHOUT ROWID;
COMMIT;
